+import { describe, expect, test } from "bun:test";
+import { render } from "../src/engine";
+
+describe("render", () => {
+  test("interpolates escaped and raw values", () => {
+    const value = `&<>"'`;
+    expect(render("{{value}}|{{{value}}}", { value })).toBe("&amp;&lt;&gt;&quot;&#39;|&<>\"'");
+    expect(render("x{{missing}}y", {})).toBe("xy");
+  });
+
+  test("renders nested conditionals and preserves whitespace", () => {
+    const template = " A\n{{#if outer}}B{{#if inner}}C{{else}}D{{/if}}{{else}}E{{/if}} Z ";
+    expect(render(template, { outer: true, inner: false })).toBe(" A\nBD Z ");
+    expect(render(template, { outer: false })).toBe(" A\nE Z ");
+  });
+
